def sequential_search(arr, element):
    """
    Perform a sequential search on the array to find the element.

    Parameters:
    arr (list): The list to search.
    element: The element to find in the list.

    Returns:
    tuple: A tuple containing a boolean indicating if the element is found and the index of the element.
    """
    for index, value in enumerate(arr):
        if value == element:
            return (True, index)
    return (False, -1)
